@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_camera_aim_assist_presets_is_packet_320(version):
    assert version.PACKETS[320] is version.CameraAimAssistPresetsPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_camera_aim_assist_presets_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_camera_aim_assist_presets_decodes_from_its_golden(packet, golden):
    assert v2225.CameraAimAssistPresetsPacket.from_bytes(golden) == packet


def test_decode_rejects_a_registry_without_its_operation_byte():
    with pytest.raises(ValueError, match="at byte"):
        v2225.CameraAimAssistPresetsPacket.from_bytes(bytes.fromhex("0000"))
